clone_cleanup_script.script:
//obfuscate the value of each field.
function obfuscate(tableName, fieldsToObfuscate) {

    for (var index = 0; index < fieldsToObfuscate.length; index++) {
        var gr = new GlideRecord(tableName);

        gr.setWorkflow(false);

        gr.addEncodedQuery(fieldsToObfuscate[index].fieldName + 'ISNOTEMPTY');
        gr.query();
        gr.setValue(fieldsToObfuscate[index].fieldName, fieldsToObfuscate[index].value);
        //Note: Line below didn't seem to work for ticket page variables so use Fix Script "HoC - OHSM - Telework - Sanitize Ticket Page" to sanitize ticket page variables
        //gr.variables[fieldsToObfuscate[index].fieldName] = fieldsToObfuscate[index].value;
        gr.updateMultiple();

    }
}

function cleanOHSMTelework() {

    //Define fields to obfuscate along with the value to obfuscate it with.
    var fieldsToObfuscate = [
        {
            fieldName: "employee_group",
            value: 'NULL_OVERRIDE'
        },
        {
            fieldName: "emergency_contact_name",
            value: "J. Doe"
        },
        {
            fieldName: "emergency_contact_telephone",
            value: "555-555-5555"
        },
        {
            fieldName: "relationship_to_employee",
            value: "Other"
        },
        {
            fieldName: "telework_location_address",
            value: "123 Street, City, Province"
        },
        {
            fieldName: "telework_telephone_number",
            value: "555-555-5555"
        }
    ];

    obfuscate("x_hccc_hoc_ohs_telework_agreement", fieldsToObfuscate);

}

cleanOHSMTelework();
